```typescript
function f1(n) { return n+1; }
function f2(n) { return n+2; }
function f3(n) { return n+3; }
function* gen1(n) {
  yield f1(n);
  yield f2(n);
  yield f3(n);
}

const g11 = gen1(0)
g11.next()
// --> { value: 1, done: false }

g11.next()
// --> { value: 2, done: false }

g11.next()
// --> { value: 3, done: false }

g11.next()
// --> { value: undefined, done: true }
```

```typescript
interface IteratorResult<T> { value: T; done: boolean; }
interface Iterator<T> { next(): IteratorResult<T>; }
```
